export function Sla({
  policy = "{{policy}}",
  target = "{{target}}",
  status = "{{status}}",
  accent = "{{accent}}",
  showTarget = {{showTarget}},
}) {
  const palette = {
    met: { background: "#A8E6C1", color: "#17532F" },
    "at risk": { background: "#E8A020", color: "#4A2E00" },
    breached: { background: "#F5C2E0", color: "#7A1440" },
  }[status] ?? {};
  return (
    <div style={{ width: 300, position: "relative", padding: "18px 18px 18px 22px", background: "#FAF7F2",
      color: "#241430", fontFamily: "system-ui, sans-serif", fontSize: 14, borderRadius: 14,
      boxShadow: "0 8px 24px rgba(36,20,48,.12)", boxSizing: "border-box" }}>
      <span aria-hidden="true" style={{ position: "absolute", left: 0, top: 14, bottom: 14, width: 5, borderRadius: 3, background: accent }} />
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 10 }}>
        <p style={{ margin: 0, fontWeight: 700, fontSize: 15 }}>{policy}</p>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "3px 10px", borderRadius: 999,
          fontWeight: 700, fontSize: 12, textTransform: "capitalize", whiteSpace: "nowrap", ...palette }}>
          {status === "met" && (
            <svg width="13" height="13" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 10.5l3.5 3.5L16 5.5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
          )}
          {status === "at risk" && (
            <svg width="13" height="13" viewBox="0 0 20 20" aria-hidden="true"><path d="M10 2L18.5 17H1.5L10 2z" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" /><path d="M10 8v4" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /><circle cx="10" cy="14.6" r="1" fill="currentColor" /></svg>
          )}
          {status === "breached" && (
            <svg width="13" height="13" viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="10" r="8" fill="none" stroke="currentColor" strokeWidth="1.6" /><path d="M7 7l6 6M13 7l-6 6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /></svg>
          )}
          {status}
        </span>
      </div>
      {showTarget && <p style={{ margin: "12px 0 0", color: "#241430b3", fontSize: 13 }}>Target: {target}</p>}
    </div>
  );
}
